def format_summary(notes):
    """Format a summary of notes."""
    if not notes:
        return "No notes found."
    summary = "\n".join(notes)
    # Add per-tag frequency summary
    tag_counts = {} 
    for note in notes:
        tags = note.get('tags', [])
        for tag in tags:
            tag_counts[tag] = tag_counts.get(tag, 0) + 1
    tag_summary = "\nTags frequency: " + ", ".join([f"{tag}: {count}" for tag, count in tag_counts.items()])
    return summary + tag_summary

